import argparse
import json
from collections import defaultdict
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.backends.backend_pdf import PdfPages


POINTS = 180

EXECUTABLES = [
    "vector-add-single-threaded",
    "vector-add-mutex",
    "vector-add-vyukov-idle",
    "vector-add-vyukov-spin",
    "vector-add-work-stealing",
    "vector-add-manual",
]

COLOURS = dict(zip(
    EXECUTABLES,
    plt.rcParams["axes.prop_cycle"].by_key()["color"],
))


def load_json(path):
    with path.open(encoding="utf-8") as f:
        data = json.load(f)

    rows = [
        row for row in data["benchmarks"]
        if row["benchmark"] == "vector_add"
    ]

    for row in rows:
        measurements = row["hyperfine"]["measurements"]

        samples = [
            m["time_wall_clock"]["value"]
            for m in measurements
            if "time_wall_clock" in m
        ]

        if not samples:
            raise ValueError(
                f"No wall-clock samples: {row.get('command')}"
            )

        unit = next(
            m["time_wall_clock"]["unit"]
            for m in measurements
            if "time_wall_clock" in m
        )

        factor = {
            "second": 1000,
            "seconds": 1000,
            "millisecond": 1,
            "milliseconds": 1,
        }.get(unit)

        if factor is None:
            raise ValueError(f"Unsupported wall-clock unit: {unit}")

        row["samples"] = np.asarray(samples, dtype=float) * factor

    return rows


def fmt(value):
    value = float(value)
    return str(int(value)) if value.is_integer() else f"{value:g}"


def kde(samples):
    """Gaussian KDE, scaled to a maximum width of 1."""
    samples = np.asarray(samples, dtype=float)
    samples = samples[np.isfinite(samples)]

    if not len(samples):
        return np.array([]), np.array([])

    spread = np.std(samples)
    if spread == 0:
        spread = max(abs(samples[0]) * 0.01, 0.01)

    bandwidth = max(1.06 * spread * len(samples) ** -0.2, 1e-9)
    low = max(0, samples.min() - 3 * bandwidth)
    high = samples.max() + 3 * bandwidth
    times = np.linspace(low, high, POINTS)

    density = np.zeros_like(times)
    for start in range(0, len(samples), 2000):
        chunk = samples[start:start + 2000]
        z = (times[:, None] - chunk[None, :]) / bandwidth
        density += np.exp(-0.5 * z**2).sum(axis=1)

    density /= len(samples) * bandwidth
    density /= density.max()

    return times, density


def plot_factor(rows, factor, fixed, output, title, normalise):
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(row[c] for c in fixed)].append(row)

    labels = {
        "vec_size": "Vector size (elements)",
        "num_threads": "Number of threads",
        "num_tasks": "Number of tasks",
        "inner_loops": "Inner loops run per build"
    }

    with PdfPages(output) as pdf:
        for key, group in sorted(groups.items()):
            fig, ax = plt.subplots(figsize=(9, 5.5))

            if factor == "executable":
                categories = sorted({r["executable"] for r in group})
            else:
                categories = sorted({r[factor] for r in group})

            group_step = 0.85
            positions = {
                value: i * group_step
                for i, value in enumerate(categories)
            }

            names = sorted(
                {r["executable"] for r in group},
                key=lambda name: np.median(np.concatenate([
                    r["samples"]
                    for r in group
                    if r["executable"] == name
                ]))
            )

            step = min(0.22, 0.7 / max(1, len(names)))
            offset_step = step * 0.45

            offsets = {
                name: (i - (len(names) - 1) / 2) * offset_step
                for i, name in enumerate(names)
            }

            for row in group:
                category = (
                    row["executable"] if factor == "executable"
                    else row[factor]
                )
                x = positions[category]

                if factor != "executable":
                    x += offsets[row["executable"]]

                samples = row["samples"]
                if normalise:
                    samples = samples / row[factor]
                times, density = kde(samples)
                if len(times):
                    ax.plot(
                        x + density * step * 0.45,
                        times,
                        linewidth=1.2,
                        label=row["executable"],
                        color=COLOURS[row["executable"]]
                    )

            ax.set_xticks(
                [positions[v] for v in categories],
                [
                    str(v) if factor == "executable" else fmt(v)
                    for v in categories
                ]
            )

            if factor == "executable":
                ax.tick_params(axis="x", labelrotation=25)
                for label in ax.get_xticklabels():
                    label.set_ha("right")

            ax.set_xlabel(
                "Executable" if factor == "executable" else labels[factor]
            )

            config = ", ".join(
                f"{col}={fmt(val)}" for col, val in zip(fixed, key)
            )
            ax.set_title(f"{title}\nFixed configuration: {config}")

            normalised_labels = {
                "vec_size": "Wall-clock time (ms / element)",
                "num_threads": "Wall-clock time (ms / thread)",
                "num_tasks": "Wall-clock time (ms / task)",
                "inner_loops": "Wall-clock time (ms / inner loop)",
            }

            ax.set_ylabel(
                normalised_labels[factor] if normalise
                else "Wall-clock time (ms)"
            )

            ax.set_yscale("log")
            ax.yaxis.minorticks_on()
            ax.grid(axis="y", which="major", alpha=0.5)
            ax.grid(axis="y", which="minor", alpha=0.3, linestyle=":")
            ax.set_axisbelow(True)

            if factor != "executable":
                handles, legend_labels = ax.get_legend_handles_labels()
                unique = dict(zip(legend_labels, handles))
                ax.legend(
                    unique.values(), unique.keys(),
                    title="Executable", fontsize="small"
                )

            fig.tight_layout()
            pdf.savefig(fig)
            plt.close(fig)

    print(f"Saved {output} ({len(groups)} pages)")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", nargs="?", default="benchmarks.json")
    parser.add_argument("-o", "--out-dir", default="plots")
    args = parser.parse_args()

    rows = load_json(Path(args.input))
    if not rows:
        parser.error("No vector_add benchmark samples found.")

    out = Path(args.out_dir)
    out.mkdir(parents=True, exist_ok=True)

    plots = [
        ("vec_size", ["num_threads", "num_tasks", "inner_loops"],
         "A - Impact of vector size", "A_vec_size.pdf", False),
        ("num_threads", ["num_tasks", "vec_size", "inner_loops"],
         "B - Impact of thread count", "B_threads.pdf", False),
        ("executable", ["num_threads", "num_tasks", "vec_size", "inner_loops"],
         "C - Impact of executable type", "C_executable.pdf", False),
        ("num_tasks", ["num_threads", "vec_size", "inner_loops"],
         "D - Impact of task count", "D_tasks.pdf", False),
        ("inner_loops", ["num_threads", "num_tasks", "vec_size"],
         "E - Impact of inner loops", "E_inner_loops.pdf", True)
    ]

    for factor, fixed, title, filename, normalise in plots:
        plot_factor(rows, factor, fixed, out / filename, title, normalise)


if __name__ == "__main__":
    main()
